const uint8_t *get_lq500_sec_metrics(int base, uint8_t ch)
{
	if (base == 0 && ch >= 0x01 && ch <= 0xFF)
		return lq500_sec_metrics_base_0000[ch - 0x01];
	if (base == 1 && ch >= 0x01 && ch <= 0xFF)
		return lq500_sec_metrics_base_0600[ch - 0x01];
	return nullptr;
}
